CREATE TABLE public.service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, kind text NOT NULL CHECK (kind IN ('contact','quote','booking','newsletter')), name text NOT NULL DEFAULT '', email text NOT NULL, phone text NOT NULL DEFAULT '', subject text NOT NULL DEFAULT '', details jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'received', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.service_requests TO anon; GRANT INSERT, SELECT ON public.service_requests TO authenticated; GRANT ALL ON public.service_requests TO service_role;
ALTER TABLE public.service_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public contact and quote requests" ON public.service_requests FOR INSERT TO anon, authenticated WITH CHECK (kind IN ('contact','quote','newsletter') AND user_id IS NULL);
CREATE POLICY "Customers create booking requests" ON public.service_requests FOR INSERT TO authenticated WITH CHECK (kind = 'booking' AND user_id = auth.uid());
CREATE POLICY "Customers read own booking requests" ON public.service_requests FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tracking_id text UNIQUE NOT NULL DEFAULT ('SDE-' || upper(replace(gen_random_uuid()::text,'-',''))), user_id uuid, origin text NOT NULL, destination text NOT NULL, sender_name text, recipient_name text, status text NOT NULL DEFAULT 'Shipment Registered' CHECK (status IN ('Shipment Registered','Picked Up','Processing','In Transit','Arrived at Sorting Facility','Out for Delivery','Delivered','Delivery Attempted','Exception / Delayed')), latest_location text, estimated_delivery timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shipments TO authenticated; GRANT ALL ON public.shipments TO service_role;
ALTER TABLE public.shipments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read private shipment details" ON public.shipments FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.shipment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shipment_id uuid NOT NULL REFERENCES public.shipments(id) ON DELETE CASCADE, status text NOT NULL, location text NOT NULL, description text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shipment_events TO authenticated; GRANT ALL ON public.shipment_events TO service_role;
ALTER TABLE public.shipment_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read shipment events" ON public.shipment_events FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.shipments s WHERE s.id = shipment_id AND s.user_id = auth.uid()));
CREATE FUNCTION public.track_shipment(p_tracking_id text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT jsonb_build_object('tracking_id',s.tracking_id,'origin',s.origin,'destination',s.destination,'status',s.status,'latest_location',s.latest_location,'estimated_delivery',s.estimated_delivery,'created_at',s.created_at,'events',COALESCE((SELECT jsonb_agg(jsonb_build_object('status',e.status,'location',e.location,'description',e.description,'occurred_at',e.occurred_at) ORDER BY e.occurred_at DESC) FROM public.shipment_events e WHERE e.shipment_id=s.id),'[]'::jsonb)) FROM public.shipments s WHERE s.tracking_id=upper(trim(p_tracking_id)) LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.track_shipment(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.track_shipment(text) TO anon, authenticated, service_role;